{"function": "() => {
    // Find heading "Number of athletes by National Olympic Committees"
    const heading = Array.from(document.querySelectorAll('h3')).find(h => h.textContent.includes('Number of athletes'));
    if (!heading) return null;
    // Find the next table after this heading
    let elem = heading.nextElementSibling;
    while (elem && elem.tagName !== 'TABLE') {
        elem = elem.nextElementSibling;
    }
    if (!elem) return null;
    const table = elem;
    const rows = table.querySelectorAll('tr');
    const data = [];
    for (let i = 0; i < rows.length; i++) {
        const cells = rows[i].querySelectorAll('td, th');
        // Skip rows that are header (maybe first row)
        if (cells.length >= 2) {
            const countryCell = cells[0];
            const athleteCell = cells[1];
            const countryText = countryCell.textContent.trim();
            const athleteText = athleteCell.textContent.trim();
            // Exclude "Total" row
            if (countryText.toLowerCase() === 'total') continue;
            const athleteNum = parseInt(athleteText.replace(/[^\d]/g, ''));
            if (!isNaN(athleteNum)) {
                data.push({
                    country: countryText,
                    athletes: athleteNum
                });
            }
        }
    }
    return data;
}"}

