{"code": "async (page) => {
    // Find table with header "Country" and "Athletes"
    const table = page.locator('table').filter({ has: page.locator('th:has-text("Country")') });
    const rows = table.locator('tr');
    const data = [];
    const count = await rows.count();
    for (let i = 1; i < count; i++) { // skip header row
        const cells = rows.nth(i).locator('td, th');
        const cellCount = await cells.count();
        if (cellCount >= 2) {
            const country = await cells.nth(0).textContent();
            const athletes = await cells.nth(1).textContent();
            // exclude total row
            if (country.toLowerCase().includes('total')) continue;
            const athleteNum = parseInt(athletes.replace(/[^\d]/g, ''));
            if (!isNaN(athleteNum)) {
                data.push({ country: country.trim(), athletes: athleteNum });
            }
        }
    }
    return data;
}"}

