{"function": "() => {
    // Find table with "Country" and "Athletes" headers
    const tables = document.querySelectorAll('table');
    let result = [];
    for (let table of tables) {
        const headers = Array.from(table.querySelectorAll('th')).map(th => th.textContent.trim());
        if (headers.includes('Country') && headers.includes('Athletes')) {
            // This is our table
            const rows = table.querySelectorAll('tbody tr');
            rows.forEach(row => {
                const cells = row.querySelectorAll('td');
                if (cells.length >= 2) {
                    const countryCell = cells[0];
                    const athleteCell = cells[1];
                    const country = countryCell.textContent.trim();
                    const athletes = athleteCell.textContent.trim();
                    result.push({ country, athletes });
                }
            });
            break;
        }
    }
    return result;
}"}

