        rows.forEach(row => {
            let cells = row.querySelectorAll('td');
            if (cells.length >= 2) {
                let countryCell = cells[0];
                let athleteCell = cells[1];
                // Get the anchor text if exists, otherwise textContent
                let anchor = countryCell.querySelector('a');
                let country = anchor ? anchor.textContent.trim() : countryCell.textContent.trim();
                let athletes = athleteCell.textContent.replace(/,/g, '').trim();
                if (country === 'Total') return;
                data.push({ country, athletes: parseInt(athletes, 10) });
            }
        });
        return data;
    });
    return rows;
}"}

