{"function": "() => {
    const tables = document.querySelectorAll('table');
    let result = [];
    for (let table of tables) {
        const headers = Array.from(table.querySelectorAll('th')).map(th => th.textContent.trim());
        if (headers.includes('Country') && headers.includes('Athletes')) {
            const rows = table.querySelectorAll('tbody tr');
            rows.forEach(row => {
                const cells = row.querySelectorAll('td');
                if (cells.length >= 2) {
                    const countryCell = cells[0];
                    const athleteCell = cells[1];
                    // Try to get the anchor text (country name)
                    let country = '';
                    const anchor = countryCell.querySelector('a');
                    if (anchor) {
                        country = anchor.textContent.trim();
                    } else {
                        // Otherwise get the text content, but remove leading/trailing whitespace and image alt
                        country = countryCell.textContent.replace(/\u00A0/g, ' ').trim();
                        // Remove any flag image filenames etc.
                        country = country.replace(/^.*?([A-Za-z].*)/, '$1');
                    }
                    const athletes = athleteCell.textContent.replace(/,/g, '').trim();
                    // Skip if country is "Total"
                    if (country === 'Total') continue;
                    result.push({ country, athletes: parseInt(athletes, 10) });
                }
            });
            break;
        }
    }
    return result;
}"}

