        const headers = await table.$$eval('th', ths => ths.map(th => th.textContent.trim()));
        if (headers.includes('Country') && headers.includes('Athletes')) {
            const rows = await table.$$('tbody tr');
            for (const row of rows) {
                const cells = await row.$$('td');
                if (cells.length >= 2) {
                    const country = await cells[0].textContent();
                    const athletes = await cells[1].textContent();
                    if (country.trim() === 'Total') continue;
                    result.push({ country: country.trim(), athletes: parseInt(athletes.replace(/,/g, ''), 10) });
                }
            }
            break;
        }
    }
