{"code": "async (page) => {
    const rows = await page.$$eval('table th:contains("Country")', (headers) => {
        // Find the table containing this header
        let table = headers[0].closest('table');
        let data = [];
        let rows = table.querySelectorAll('tbody tr');
        rows.forEach(row => {
            let cells = row.querySelectorAll('td');
            if (cells.length >= 2) {
                let countryCell = cells[0];
                let athleteCell = cells[1];
                // Get the anchor text if exists, otherwise textContent
                let anchor = countryCell.querySelector('a');
                let country = anchor ? anchor.textContent.trim() : countryCell.textContent.trim();
                let athletes = athleteCell.textContent.replace(/,/g, '').trim();
                if (country === 'Total') return;
                data.push({ country, athletes: parseInt(athletes, 10) });
            }
        });
        return data;
    });
    return rows;
}"}

{"function": "() => {
    const tables = document.querySelectorAll('table');
    for (const table of tables) {
        const ths = table.querySelectorAll('th');
        let hasCountry = false, hasAthletes = false;
        ths.forEach(th => {
            const text = th.textContent.trim();
            if (text === 'Country') hasCountry = true;
            if (text === 'Athletes') hasAthletes = true;
        });
        if (hasCountry && hasAthletes) {
            const rows = table.querySelectorAll('tbody tr');
            const data = [];
            rows.forEach(row => {
                const cells = row.querySelectorAll('td');
                if (cells.length >= 2) {
                    const countryCell = cells[0];
                    const athleteCell = cells[1];
                    const anchor = countryCell.querySelector('a');
                    const country = anchor ? anchor.textContent.trim() : countryCell.textContent.trim();
                    const athletes = athleteCell.textContent.replace(/,/g, '').trim();
                    if (country === 'Total') return;
                    data.push({ country, athletes: parseInt(athletes, 10) });
                }
            });
            return data;
        }
    }
    return [];
}"}

